def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Draw 1s between any pair of 1s on a diagonal.
    connectors = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr != 0 and abs(dr) == abs(dc):
                connectors.append((r1, c1, r2, c2))
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                for k in range(1, abs(dr)):
                    out[r1 + sr * k][c1 + sc * k] = 1

    # A 6 on a connector draws a full line of 6 in the perpendicular direction.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            lies_on_connector = False
            for r1, c1, r2, c2 in connectors:
                if abs(r - r1) == abs(c - c1) and abs(r - r2) == abs(c - c2):
                    if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                        lies_on_connector = True
                        break
            if lies_on_connector:
                # The connector has slope +1, so its perpendicular has slope -1, and vice versa.
                slope = 1 if (r2 - r1) * (c2 - c1) < 0 else -1
                for rr in range(h):
                    cc = c + slope * (rr - r)
                    if 0 <= cc < w and grid[rr][cc] != 1:
                        out[rr][cc] = 6
    return out
